class file_close(FileSummary):
    def run(self, fd_bv):
        fd = self.load_int(fd_bv)
        f = self.fs.close_file
        status = self.call_write_op_fds(f, fd)
        return status


class file_write(FileSummary):
    def run(self, fd_bv, buffer_addr, count_bv):
        fd = self.load_int(fd_bv)
        buffer = self.load_string(buffer_addr, include_null=True)
        count = self.load_numeric(count_bv)
        f = self.fs.write_file
        n = self.call_write_op_fds(f, fd, buffer, count)
        return self.ssize_t(n)


class file_read(FileSummary):
    def run(self, fd_bv, buffer, count_bv):
        fd = self.load_int(fd_bv)
        count = self.load_numeric(count_bv)
        f = self.fs.read_file
        n = self.call_write_op_fds(f, fd, buffer, count)
        return self.ssize_t(n)


class FILE_from_fd(FileSummary):
    def run(self, fd_bv):
        fd = self.load_int(fd_bv)
        f = self.fs.FILE_from_fd
        fp = self.call_read_op_fds(f, fd, default=0)
        return fp


class fd_from_FILE(FileSummary):
    def run(self, fp_bv):
        fp = self.load_int(fp_bv)
        f = self.fs.fd_from_FILE
        fd = self.call_read_op_fds(f, fp, signed=False, invalid=0)
        return fd


class file_offset(FileSummary):
    def run(self, fd_bv):
        fd = self.load_int(fd_bv)
        f = self.fs.file_offset
        offset = self.call_read_op_fds(f, fd)
        return self.ssize_t(offset)


class file_set_offset(FileSummary):
    def run(self, fd_bv, offset_bv):
        fd = self.load_int(fd_bv)
        offset = self.load_numeric(offset_bv)
        f = self.fs.file_set_offset
        offset = self.call_write_op_fds(f, fd, offset)
        return self.ssize_t(offset)


class file_size(FileSummary):
    def run(self, fd_bv):
        fd = self.load_int(fd_bv)
        f = self.fs.file_size
        offset = self.call_read_op_fds(f, fd)
        return self.ssize_t(offset)


class file_set_size(FileSummary):
    def run(self, fd_bv, size_bv):
    if (replaced)
        fd_track_close(replaced);

    t = fd_track_find(fd);
    if (t)
        fd_track_add(r, t->path, t->flags);

    return r;
}

int sbv_close(int fd) {
    fd_track_t *t = fd_track_find(fd);

    if (t)
        fd_track_close(t);

    return close(fd);
}

int sbv_fclose(FILE *fp) {
    fd_track_t *t = fd_track_find(fileno(fp));

    if (t)
        fd_track_close(t);

    return fclose(fp);
}

/* File API (concrete) --------------------------------------------------- */

/*
 * Concrete counterparts of the summary's file primitives, for the generated
 * test's setup. Descriptors handed to the function under test go through
 * sbv_open so they are tracked; the probe in __file_create does not, since
 * the symbolic side's __file_create opens no descriptor.
 */

int __file_create(const char *name) {
    int fd;

    if (!name || !name[0])
        return -1;

    fd = open(name, O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (fd < 0)
        return -1;

    close(fd);
    return 1;
}

/* fopen-style mode strings, read the way the symbolic side's str_to_flag
 * reads them: 'b', 't', 'c' and 'e' are ignored. */
int __file_open(const char *name, const char *flags) {
    int plus = 0, oflags;
    const char *c;

    if (!flags || !flags[0])
        return -1;

    for (c = flags + 1; *c; c++) {
        if (*c == '+')
            plus = 1;
        else if (*c != 'b' && *c != 't' && *c != 'c' && *c != 'e')
            return -1;
    }

    switch (flags[0]) {
    case 'r':
        oflags = plus ? O_RDWR : O_RDONLY;
        break;
    case 'w':
        oflags = (plus ? O_RDWR : O_WRONLY) | O_CREAT | O_TRUNC;
        break;
    case 'a':
        oflags = (plus ? O_RDWR : O_WRONLY) | O_CREAT | O_APPEND;
        break;
    default:
        return -1;
    }

    return sbv_open(name, oflags, 0644);
}

ssize_t __file_write(int fd, const void *buf, size_t count) {
    return write(fd, buf, count);
}

/* Through sbv_close, so the descriptor is no longer tracked: closed, it no
 * longer exists, as on the symbolic side. */
int __file_close(int fd) {
    return sbv_close(fd) == 0 ? 0 : -1;
}

ssize_t __file_set_offset(int fd, size_t offset) {
