/* Up to `cap` bytes of the file at `path`. Zero if it cannot be read. */
static size_t read_path(const char *path, unsigned char *buf, size_t cap) {
    size_t total = 0;
    ssize_t n;
    int fd;

    fd = open(path, O_RDONLY);
    if (fd < 0)
        return 0;

    while (total < cap && (n = read(fd, buf + total, cap - total)) > 0)
        total += (size_t)n;

    close(fd);
    return total;
}

